<script setup>
import {computed} from 'vue';import {PanelTop,ChevronRight,Download,Upload} from 'lucide-vue-next';
import Control from './Control.vue';import HeaderRenderer from '../../studio/HeaderRenderer.vue';import HeaderAppearance from '../../studio/HeaderAppearance.vue';
import {presets,validateConfig} from '../../studio/presets.js';import {lineEffects} from '../../studio/lineEffects.js';import {resolveHeaderConfig,applyHeaderConfig,headerPreset} from '../header.js';import {themeById} from '../catalog.js';import {downloadBlob} from '../../studio/export.js';
const props=defineProps({node:Object,theme:String});const emit=defineEmits(['record','edit','notify']);
const config=computed(()=>resolveHeaderConfig(props.node,themeById(props.theme))),preset=computed(()=>presets.find(p=>p.id===config.value.presetId));
function patch(value){if(!props.node.props.headerConfig)applyHeaderConfig(props.node,config.value);Object.assign(props.node.props.headerConfig,value);const c=props.node.props.headerConfig;Object.assign(props.node.props,{preset:c.presetId,text:c.title,subtitle:c.subtitle,titleSize:c.fontSize});}
function choose(id){const p=presets.find(p=>p.id===id);if(p){applyHeaderConfig(props.node,headerPreset(config.value,p));emit('record');}}
function lines(key,value){patch({lines:config.value.lines.map(l=>({...l,[key]:value}))});emit('record');}
function effect(id){const e=lineEffects.find(e=>e.id===id);if(e){patch({lines:config.value.lines.map(l=>({...l,effect:e.id,width:e.width,duration:e.duration,tail:e.tail,glow:e.glow}))});emit('record');}}
function exportJSON(){downloadBlob(new Blob([JSON.stringify(config.value,null,2)],{type:'application/json'}),'header.config.json');}
async function importJSON(event){const file=event.target.files?.[0];event.target.value='';if(!file)return;try{if(file.size>6*1024*1024)throw Error('配置文件最大 6 MB');applyHeaderConfig(props.node,validateConfig(JSON.parse(await file.text())));emit('record');emit('notify','Header 配置已导入，可继续进入设计器编辑');}catch(e){emit('notify',e.message);}}
</script>
<template><div class="aw-header-settings"><div class="aw-header-sample"><HeaderRenderer :config="config" :playing="false"/><span>{{preset?.en||'CUSTOM COMPOSITION'}}</span></div><button class="aw-header-entry" @click="emit('edit')"><span><PanelTop :size="17"/><span><strong>进入 Header 设计器</strong><small>{{config.lines.length}} 条光轨 · 配置双向同步</small></span></span><ChevronRight :size="16"/></button><Control :model-value="config.presetId" label="背景与光轨预设" type="select" :options="[...(config.presetId==='custom'?[{id:'custom',name:'自定义设计'}]:[]),...presets.map(p=>({id:p.id,name:p.name}))]" @update:model-value="choose"/><p class="aw-field-note">切换预设保留标题，背景、轮廓与光效成套应用。</p><HeaderAppearance :config="config" compact @patch="patch" @commit="emit('record')"/><details class="aw-header-flight"><summary>飞线快捷设置 <span>{{config.lines.length}} TRACKS</span></summary><Control :model-value="new Set(config.lines.map(l=>l.effect)).size===1?config.lines[0]?.effect:'mixed'" label="全部光轨效果" type="select" :options="[{id:'mixed',name:'各轨道独立效果'},...lineEffects.map(e=>({id:e.id,name:e.name}))]" @update:model-value="effect"/><Control :model-value="config.lines[0]?.duration||5.5" label="统一运动周期" :min="1" :max="20" :step=".5" unit="s" @update:model-value="lines('duration',$event)"/><Control :model-value="config.lines.some(l=>l.visible)" label="显示飞线" type="toggle" @update:model-value="lines('visible',$event)"/><p class="aw-field-note">逐条编辑、绘制节点、裁剪和背景上传均可在设计器中完成。</p></details><div class="aw-header-config-actions"><button @click="exportJSON"><Download :size="12"/>导出配置</button><label><Upload :size="12"/>导入配置<input type="file" accept=".json,application/json" hidden @change="importJSON"/></label></div></div></template>
<style scoped>
.aw-header-sample{position:relative;margin-top:15px;border-radius:6px;overflow:hidden;background:#081623;box-shadow:0 3px 12px #16302b12}.aw-header-sample>span{position:absolute;left:10px;bottom:6px;font:5px monospace;letter-spacing:1.3px;color:#9bbec080}.aw-header-entry{display:flex;align-items:center;justify-content:space-between;width:100%;text-align:left;padding:13px 10px!important;background:#edf5f1!important;border:1px solid #d7e8df!important;border-radius:6px!important;color:#47765f!important;margin:12px 0!important}.aw-header-entry>span{display:flex;align-items:center;gap:9px}.aw-header-entry strong{display:block;font-size:11px;font-weight:550}.aw-header-entry small{display:block;font-size:8px;color:#8aa697;margin-top:5px}.aw-header-entry:hover{background:#e5f1e9!important}.aw-header-flight{border-top:1px solid #e6ece8;margin-top:12px;padding:14px 0}.aw-header-flight summary{display:flex;align-items:center;font-size:11px;color:#4d685c;cursor:pointer;list-style:none}.aw-header-flight summary:before{content:'›';margin-right:7px}.aw-header-flight[open] summary:before{transform:rotate(90deg)}.aw-header-flight summary>span{margin-left:auto;font:6px monospace;color:#a4b6ac}.aw-header-config-actions{display:flex;justify-content:space-between;border-top:1px solid #e6ece8;padding-top:14px;gap:12px}.aw-header-config-actions>button,.aw-header-config-actions>label{display:flex;align-items:center;gap:6px;font-size:9px;color:#71907d;cursor:pointer}
</style>
